wrap.querySelectorAll('[data-doc]').forEach(b=>b.addEventListener('click',()=>{b.blur();hideDocImageBar();const a=b.dataset.doc;if(a==='image')document.getElementById('docImageInput').click();else if(a==='add-page'){const p=document.createElement('div');p.className='doc-page';p.contentEditable='true';p.innerHTML='<p></p>';document.getElementById('docPages').appendChild(p);updateDocLabel()}else if(a==='remove-page'){const all=document.querySelectorAll('.doc-page');if(all.length>1){all[all.length-1].remove();updateDocLabel()}}else if(a==='clear'){document.querySelectorAll('.doc-page').forEach((p,i)=>p.innerHTML=i?'<p></p>':'<p></p>')}}));
document.getElementById('docImageInput').addEventListener('change',async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;insertDocImage(await readDocImage(f))});
document.addEventListener('selectionchange',updateDocToolbarState);
