function setProgress(p,label){const bar=document.getElementById('modalProgress'),fill=document.getElementById('modalProgressFill'),lbl=document.getElementById('modalProgressLabel');if(!bar)return;bar.classList.add('show');bar.setAttribute('aria-hidden','false');if(lbl){lbl.textContent=label||'';lbl.classList.toggle('show',!!label)}if(p==null||isNaN(p)){fill.classList.add('indeterminate');fill.style.width='100%';bar.removeAttribute('aria-valuenow')}else{fill.classList.remove('indeterminate');const v=Math.max(2,Math.min(100,p));fill.style.width=v+'%';bar.setAttribute('aria-valuenow',String(Math.round(v)))}}
function hideProgress(){const bar=document.getElementById('modalProgress');if(!bar)return;bar.classList.remove('show');bar.setAttribute('aria-hidden','true');document.getElementById('modalProgressFill').classList.remove('indeterminate');const lbl=document.getElementById('modalProgressLabel');if(lbl){lbl.textContent='';lbl.classList.remove('show')}}
function parseHocrWords(hocr){const words=[],re=/<span[^>]*class=['"]ocrx_word['"][^>]*title=['"][^'"]*bbox ([\d.]+) ([\d.]+) ([\d.]+) ([\d.]+)[^'"]*['"][^>]*>([\s\S]*?)<\/span>/g;let m;while((m=re.exec(hocr||''))){const tmp=document.createElement('textarea');tmp.innerHTML=m[5].replace(/<[^>]*>/g,'');const text=tmp.value.trim();if(text)words.push({x0:+m[1],y0:+m[2],x1:+m[3],y1:+m[4],text})}return words}
async function runOcrPage(pdf,i,lang,wantHocr){const page=await pdf.getPage(i),base=page.getViewport({scale:1}),vp=page.getViewport({scale:Math.min(2,1400/base.width)});const canvas=document.createElement('canvas');canvas.width=Math.ceil(vp.width);canvas.height=Math.ceil(vp.height);const ctx=canvas.getContext('2d',{alpha:false});ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);await page.render({canvasContext:ctx,viewport:vp}).promise;const Tesseract=await loadTesseract();const {data}=await Tesseract.recognize(canvas,lang,{langPath:'https://tessdata.projectnaptha.com/4.0.0',workerPath:'https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/worker.min.js',corePath:'https://cdn.jsdelivr.net/npm/tesseract.js-core@5'},{text:true,hocr:wantHocr});const result={text:data.text||'',hocr:data.hocr||'',width:canvas.width,height:canvas.height,size:base};if(wantHocr)result.jpg=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.8));canvas.width=1;canvas.height=1;return result}
async function runOcr(file,report){const lang=document.getElementById('ocrLang').value,mode=(document.querySelector('input[name="ocrOut"]:checked')||{}).value||'txt',status=document.getElementById('ocrStatus'),base=filenameBase(file.name);const bytes=new Uint8Array(await file.arrayBuffer()),pdf=await pdfjsLib.getDocument({data:bytes}).promise;
if(mode==='pdf'){const out=await PDFDocument.create(),font=await out.embedFont(StandardFonts.Helvetica);for(let i=1;i<=pdf.numPages;i++){report((i-1)/pdf.numPages*.9);status.textContent=`Membaca halaman ${i} dari ${pdf.numPages} dengan OCR…`;const r=await runOcrPage(pdf,i,lang,true);const img=await out.embedJpg(await r.jpg.arrayBuffer());const pg=out.addPage([r.size.width,r.size.height]);pg.drawImage(img,{x:0,y:0,width:r.size.width,height:r.size.height});const sx=r.size.width/r.width,sy=r.size.height/r.height;for(const w of parseHocrWords(r.hocr)){const size=(w.y1-w.y0)*sy*.9;if(size<2)continue;pg.drawText(w.text,{x:w.x0*sx,y:r.size.height-w.y1*sy,size,font,color:rgb(0,0,0),opacity:0})}}pdf.destroy();status.textContent='PDF hasil pindaian yang bisa dicari siap diunduh.';return {name:`${base}-ocr-cari.pdf`,data:await out.save()}}
const pages=[];for(let i=1;i<=pdf.numPages;i++){report((i-1)/pdf.numPages*.9);status.textContent=`Membaca halaman ${i} dari ${pdf.numPages} dengan OCR…`;const r=await runOcrPage(pdf,i,lang,false);pages.push(`— Halaman ${i} —\n${r.text.trim()}`)}pdf.destroy();status.textContent='Teks berhasil dibaca. Hasil siap diunduh.';return {name:`${base}-teks.txt`,data:pages.join('\n\n'),type:'text/plain;charset=utf-8'}}
async function runSingle(id,file,report){const base=filenameBase(file.name);
if(id==='compress'){const quality=document.querySelector('input[name="quality"]:checked').value;report(.15);const out=await rasterize(file,quality,frac=>report(.15+frac*.75));if(out.byteLength>=file.size){compressionFallbackCount++;return {name:file.name,data:file,type:file.type||'application/pdf'}}return {name:`${base}-kompres.pdf`,data:out}}
if(id==='rotate'){report(.3);const {doc}=await readPDF(file),deg=+document.querySelector('input[name="rotation"]:checked').value;doc.getPages().forEach(p=>p.setRotation(degrees((p.getRotation().angle+deg)%360)));report(.85);return {name:`${base}-diputar.pdf`,data:await doc.save()}}
if(id==='extract'){report(.25);const {doc}=await readPDF(file),ids=parsePages(document.getElementById('rangeField').value,doc.getPageCount()),piece=await PDFDocument.create(),pages=await piece.copyPages(doc,ids);pages.forEach(p=>piece.addPage(p));report(.85);return {name:`${base}-ekstrak.pdf`,data:await piece.save()}}
if(id==='number'){report(.25);const {doc}=await readPDF(file),font=await doc.embedFont(StandardFonts.Helvetica),start=Math.max(1,parseInt(document.getElementById('numberStart').value)||1);doc.getPages().forEach((p,i)=>{const {width}=p.getSize(),text=String(start+i);p.drawText(text,{x:(width-font.widthOfTextAtSize(text,10))/2,y:18,size:10,font,color:rgb(.48,.51,.58)})});report(.85);return {name:`${base}-bernomor.pdf`,data:await doc.save()}}
if(id==='watermark'){const text=document.getElementById('watermarkText').value.trim();if(!text)throw Error('Tulis teks tanda air yang ingin digunakan.');report(.25);const {doc}=await readPDF(file),font=await doc.embedFont(StandardFonts.HelveticaBold);doc.getPages().forEach(p=>{const {width,height}=p.getSize(),size=Math.min(48,Math.max(20,width/10));p.drawText(text,{x:width*.15,y:height*.45,size,font,color:rgb(.48,.52,.62),opacity:.2,rotate:degrees(-32)})});report(.85);return {name:`${base}-bertanda-air.pdf`,data:await doc.save()}}
if(id==='protect'){const pw=document.getElementById('protectPassword').value,owner=document.getElementById('protectOwner').value.trim();if(pw.length<4)throw Error('Gunakan kata sandi minimal 4 karakter.');report(.2);const doc=await CantooPDFDocument.load(await file.arrayBuffer(),{ignoreEncryption:true});if(doc.isEncrypted)throw Error('PDF ini sudah terkunci. Gunakan "Buka kunci PDF" terlebih dahulu.');const restrict=document.querySelector('input[name="protectMode"]:checked').value==='restrict';doc.encrypt({userPassword:pw,ownerPassword:owner||pw,permissions:restrict?{printing:false,modifying:false,copying:false,annotating:false,fillingForms:false,contentAccessibility:false,documentAssembly:false}:{printing:'highResolution',modifying:true,copying:true,annotating:true,fillingForms:true,contentAccessibility:true,documentAssembly:true}});report(.85);return {name:`${base}-terkunci.pdf`,data:await doc.save({useObjectStreams:true})}}
if(id==='unlock'){const pw=document.getElementById('unlockPassword').value;report(.2);let doc;try{doc=await CantooPDFDocument.load(await file.arrayBuffer(),{password:pw})}catch(e){if(e.name==='EncryptedPDFError'||/encrypt|password/i.test(e.message))throw Error('Kata sandi salah atau file tidak bisa dibuka. Periksa kembali kata sandi PDF Anda.');throw e}report(.85);return {name:`${base}-terbuka.pdf`,data:await doc.save()}}
if(id==='ocr')return runOcr(file,report);
throw Error('Alat tidak dikenal.')}
async function processTool(){if(activeTool.id!=='doc'&&!selectedFiles.length){showError(activeTool.input==='images'?'Pilih setidaknya satu gambar.':'Pilih file PDF terlebih dahulu.');return}if(activeTool.id==='merge'&&selectedFiles.length<2){showError('Tambahkan minimal dua file PDF untuk digabungkan.');return}const button=document.getElementById('modalAction');button.disabled=true;button.classList.add('loading');button.innerHTML='<span class="button-spinner" aria-hidden="true"></span><span>Sedang memproses…</span>';document.getElementById('modalError').classList.remove('show');setProgress(null,'Menyiapkan…');try{compressionFallbackCount=0;
switch(activeTool.id){
case'split':{const {doc}=await readPDF(selectedFiles[0]),total=doc.getPageCount(),ranges=currentSplitRanges();if(!ranges.length)throw Error('Tentukan setidaknya satu rentang halaman.');setProgress(30,`Menyiapkan ${ranges.length} rentang…`);const files=[];for(let i=0;i<ranges.length;i++){const piece=await PDFDocument.create(),copied=await piece.copyPages(doc,ranges[i].ids);copied.forEach(p=>piece.addPage(p));const suffix=ranges.length>1?`-bagian-${i+1}`:'';files.push({name:`${filenameBase(selectedFiles[0].name)}-halaman-${ranges[i].slug}${suffix}.pdf`,data:await piece.save()});setProgress(30+(i+1)/ranges.length*50,'Membuat file hasil…')}if(files.length===1)download(files[0].data,files[0].name);else{setProgress(88,'Membuat arsip ZIP…');const zipped={};for(const f of files)zipped[f.name]=new Uint8Array(f.data);download(fflate.zipSync(zipped,{level:6}),`${filenameBase(selectedFiles[0].name)}-hasil-pisah.zip`,'application/zip')}setProgress(100,'Selesai');break}
case'merge':{const merged=await PDFDocument.create(),files=selectedFiles;for(let i=0;i<files.length;i++){setProgress(i/files.length*90,`Menyatukan file ${i+1} dari ${files.length}…`);const {doc}=await readPDF(files[i]),pages=await merged.copyPages(doc,doc.getPageIndices());pages.forEach(p=>merged.addPage(p))}setProgress(95,'Menyimpan…');download(await merged.save(),`paperly-gabungan-${Date.now()}.pdf`);setProgress(100,'Selesai');break}
case'images':{const pdf=await PDFDocument.create(),files=selectedFiles;for(let i=0;i<files.length;i++){setProgress(i/files.length*90,`Menyisipkan gambar ${i+1} dari ${files.length}…`);const f=files[i],bytes=await f.arrayBuffer(),img=f.type==='image/png'?await pdf.embedPng(bytes):await pdf.embedJpg(bytes);const page=pdf.addPage([img.width,img.height]);page.drawImage(img,{x:0,y:0,width:img.width,height:img.height})}setProgress(95,'Menyimpan…');download(await pdf.save(),`gambar-ke-pdf-${Date.now()}.pdf`);setProgress(100,'Selesai');break}
case'edit':{setProgress(50,'Menyusun halaman…');download(await saveEditorPDF(f=>setProgress(30+f*.6)),`${filenameBase(selectedFiles[0].name)}-suntingan.pdf`);setProgress(100,'Selesai');break}
case'doc':{download(await exportDocToPdf(f=>setProgress(25+f*.65,'Merakit halaman PDF…')),'paperly-dokumen.pdf');setProgress(100,'Selesai');break}
case'toWord':{const pages=await extractPdfLines(selectedFiles[0],f=>setProgress(15+f*.6,'Membaca teks PDF…'));setProgress(85,'Menyusun dokumen Word…');download(buildDocx(pages),`${filenameBase(selectedFiles[0].name)}.docx`,'application/vnd.openxmlformats-officedocument.wordprocessingml.document');setProgress(100,'Selesai');break}
case'toPpt':{download(await buildPptx(selectedFiles[0],f=>setProgress(15+f*.7,'Merender halaman jadi slide…')),`${filenameBase(selectedFiles[0].name)}.pptx`,'application/vnd.openxmlformats-officedocument.presentationml.presentation');setProgress(100,'Selesai');break}
case'pdfa':{setProgress(5,'Merender halaman dan menyiapkan metadata PDF/A…');download(await convertToPdfA(selectedFiles[0],f=>setProgress(5+f*.75,'Merender halaman PDF/A…')),`${filenameBase(selectedFiles[0].name)}-pdfa.pdf`);setProgress(100,'Selesai');break}
 case'toJpg':{const images=await renderPdfPagesToJpg(selectedFiles[0],f=>setProgress(10+f*.78,'Merender halaman JPG…'));if(images.length===1){download(images[0].data,images[0].name,'image/jpeg')}else{setProgress(92,'Membuat arsip ZIP…');const files={};for(const image of images)files[image.name]=image.data;download(fflate.zipSync(files,{level:6}),`${filenameBase(selectedFiles[0].name)}-jpg.zip`,'application/zip')}setProgress(100,'Selesai');break}
case'redact':{setProgress(5,'Menyusun halaman redaksi…');download(await applyRedaction(selectedFiles[0],f=>setProgress(5+f*.8,'Merender halaman yang ditandai…')),`${filenameBase(selectedFiles[0].name)}-redaksi.pdf`);setProgress(100,'Selesai');break}
 default:{const files=selectedFiles,total=files.length,outputs=[];for(let i=0;i<total;i++){const f=files[i];const report=frac=>setProgress(((i+(frac==null?.5:frac))/total)*100,total>1?`File ${i+1}/${total} — ${f.name}`:f.name);outputs.push(await runSingle(activeTool.id,f,report))}if(outputs.length===1){const o=outputs[0];download(o.data,o.name,o.type)}else{setProgress(96,'Membuat arsip ZIP…');const z={};for(let i=0;i<outputs.length;i++){const o=outputs[i];let n=o.name,c=1;while(z[n])n=o.name.replace(/(\.[^./]+)?$/,`-${++c}$1`);z[n]=new Uint8Array(o.data instanceof Blob?await o.data.arrayBuffer():o.data)}download(fflate.zipSync(z,{level:6}),`${filenameBase(files[0].name)}-${activeTool.id}-hasil.zip`,'application/zip')}setProgress(100,'Selesai')}}
closeModal();hideProgress();showToast(activeTool.id==='compress'?(compressionFallbackCount?'Hasil kompresi lebih besar pada '+compressionFallbackCount+' file, jadi file aslinya dipertahankan.':'PDF selesai dikompres dan siap diunduh.'):'Selesai! File hasil sudah diunduh.');}catch(e){hideProgress();showError(e.message||'Terjadi kesalahan saat memproses file.');}finally{button.disabled=false;button.classList.remove('loading');button.innerHTML=`<span>${activeTool.action}</span><span>↗</span>`}}

document.getElementById('modalAction').addEventListener('click',processTool);document.getElementById('modalClose').addEventListener('click',closeModal);document.getElementById('modalCancel').addEventListener('click',closeModal);modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(sidebarOpen){setSidebarOpen(false,{restoreFocus:true});return}if(document.getElementById('docWritePage').classList.contains('open')){closeDocPage();return}closeModal()}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.getElementById('toolSearch').focus()}});
document.querySelectorAll('[data-tool]').forEach(b=>b.addEventListener('click',()=>{setSidebarOpen(false);openTool(b.dataset.tool)}));document.getElementById('toolSearch').addEventListener('input',e=>renderTools(e.target.value));document.querySelector('[data-scroll-tools]').addEventListener('click',()=>document.getElementById('toolsSection').scrollIntoView({behavior:'smooth'}));
const sidebar=document.getElementById('sidebar'),sidebarScrim=document.getElementById('sidebarScrim'),mobileMenu=document.getElementById('mobileMenu'),mainContent=document.querySelector('.main-content'),mobileQuery=window.matchMedia('(max-width:860px)');let sidebarOpen=false;
function setSidebarOpen(open,options={}){sidebarOpen=!!open&&mobileQuery.matches;sidebar.classList.toggle('open',sidebarOpen);sidebarScrim.classList.toggle('open',sidebarOpen);document.body.classList.toggle('sidebar-open',sidebarOpen);mobileMenu.setAttribute('aria-expanded',String(sidebarOpen));mobileMenu.setAttribute('aria-label',sidebarOpen?'Tutup menu':'Buka menu');const hidden=mobileQuery.matches&&!sidebarOpen;sidebar.toggleAttribute('inert',hidden);mainContent.toggleAttribute('inert',mobileQuery.matches&&sidebarOpen);if(hidden)sidebar.setAttribute('aria-hidden','true');else sidebar.removeAttribute('aria-hidden');if(sidebarOpen){requestAnimationFrame(()=>{if(sidebarOpen)sidebar.focus({preventScroll:true})})}else if(options.restoreFocus)mobileMenu.focus({preventScroll:true})}
mobileMenu.addEventListener('click',()=>setSidebarOpen(!sidebarOpen));sidebarScrim.addEventListener('click',()=>setSidebarOpen(false));document.querySelector('.brand').addEventListener('click',()=>setSidebarOpen(false));mobileQuery.addEventListener?.('change',()=>setSidebarOpen(false));setSidebarOpen(false);
document.querySelectorAll('.nav-link').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();document.querySelectorAll('.nav-link').forEach(n=>n.classList.remove('active'));a.classList.add('active');let target=a.dataset.nav==='tools'?'toolsSection':a.dataset.nav==='recent'?'toolsSection':'homeSection';document.getElementById(target).scrollIntoView({behavior:'smooth'});setSidebarOpen(false)}));
const now=new Date(),dateLabel=document.getElementById('todayLabel');dateLabel.textContent=new Intl.DateTimeFormat('id-ID',{weekday:'long',day:'numeric',month:'long'}).format(now);
